    pub fn decorateFloor8(
        &self,
        world: &GenWorld,
        random: &Random,
        floor: i32,
        bottom: i32,
        top: i32,
        ladderUpDir: i32,
        ladderDownDir: i32,
        sbb: StructureBox,
    )
    {
        match self.m_kind
        {
            Kind::DarkTowerBalcony
            | Kind::DarkTowerBossBridge
            | Kind::DarkTowerBossTrap
            | Kind::DarkTowerBridge
            | Kind::DarkTowerEntrance
            | Kind::DarkTowerEntranceBridge
            | Kind::DarkTowerMain
            | Kind::DarkTowerMainBridge
            | Kind::DarkTowerWing
            | Kind::FinalCastleBellTower21
            | Kind::FinalCastleDamagedTower
            | Kind::FinalCastleDungeonEntrance
            | Kind::FinalCastleDungeonExit
            | Kind::FinalCastleDungeonRoom31
            | Kind::FinalCastleEntranceBottomTower
            | Kind::FinalCastleEntranceSideTower
            | Kind::FinalCastleEntranceTower
            | Kind::FinalCastleLargeTower
            | Kind::FinalCastleMazeTower13
            | Kind::FinalCastleStairTower
            | Kind::FinalCastleWreckedTower
            | Kind::IceTowerStairs
            | Kind::TowerBridge
            | Kind::TowerMain
            | Kind::TowerOutbuilding
            | Kind::TowerWing =>
            {
                tower_wing::decorateFloor8(self, world, random, floor, bottom, top, ladderUpDir, ladderDownDir, sbb)
            }
            Kind::IceTowerBossWing => ice_tower_boss_wing::decorateFloor8(
                self,
                world,
                random,
                floor,
                bottom,
                top,
                ladderUpDir,
                ladderDownDir,
                sbb,
            ),
            Kind::IceTowerEntrance | Kind::IceTowerMain | Kind::IceTowerWing =>
            {
                ice_tower_wing::decorateFloor8(self, world, random, floor, bottom, top, ladderUpDir, ladderDownDir, sbb)
            }
            Kind::MushroomTowerBridge
            | Kind::MushroomTowerMain
            | Kind::MushroomTowerMainBridge
            | Kind::MushroomTowerWing => mushroom_tower_wing::decorateFloor8(
                self,
                world,
                random,
                floor,
                bottom,
                top,
                ladderUpDir,
                ladderDownDir,
                sbb,
            ),
            _ => unreachable!("decorateFloor on {:?}", self.m_kind),
        }
    }

